MERGE INTO CHB_SALER_STL_DEAL_INFO L USING (
select #{item.registSeqno,jdbcType=VARCHAR} REGIST_SEQNO, #{item.status,jdbcType=VARCHAR} DATA_STATUS , #{item.accountName,jdbcType=VARCHAR} ACCOUNT_NAME , #{item.institutionCode,jdbcType=VARCHAR} INSTITUTION_CODE, #{item.prdRegistCode,jdbcType=VARCHAR} PRD_REGIST_CODE, #{item.accountNo,jdbcType=VARCHAR} ACCOUNT_NO, #{item.tradeNo,jdbcType=VARCHAR} TRADE_NO, #{item.tradePs,jdbcType=VARCHAR} TRADE_PS , #{item.tradeCounterAccNo,jdbcType=VARCHAR} TRADE_COUNTER_ACC_NO , #{item.tradeCounterAccName,jdbcType=VARCHAR} TRADE_COUNTER_ACC_NAME , #{item.tradeCounterAccBankName,jdbcType=VARCHAR}TRADE_COUNTER_ACC_BANK_NAME , #{item.tradeCounterAccBankNo,jdbcType=VARCHAR} TRADE_COUNTER_ACC_BANK_NO , #{item.tradeCcy,jdbcType=VARCHAR} TRADE_CCY , #{item.tradeAmt,jdbcType=DECIMAL}TRADE_AMT , #{item.tradeVdate,jdbcType=DATE} TRADE_VDATE , #{item.tradeTime,jdbcType=TIMESTAMP} TRADE_TIME , #{item.postscript,jdbcType=VARCHAR} POSTSCRIPT , #{item.remark,jdbcType=VARCHAR} REMARK , sysdate RECEPT_DATE , #{item.orgCode,jdbcType=VARCHAR} CREATE_DEPT, #{item.createDept,jdbcType=VARCHAR} ORG_CODE , #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER , #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME, #{item.updateUser,jdbcType=VARCHAR} CREATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} CREATE_TIME from dual
) TEMP ON (L.INSTITUTION_CODE = TEMP.INSTITUTION_CODE and L.TRADE_NO = TEMP.TRADE_NO and L.ACCOUNT_NO = TEMP.ACCOUNT_NO and L.PRD_REGIST_CODE = TEMP.PRD_REGIST_CODE) WHEN MATCHED THEN UPDATE SET L.REGIST_SEQNO = TEMP.REGIST_SEQNO ,L.DATA_STATUS = TEMP.DATA_STATUS ,L.ACCOUNT_NAME = TEMP.ACCOUNT_NAME ,L.TRADE_PS = TEMP.TRADE_PS ,L.TRADE_COUNTER_ACC_NO = TEMP.TRADE_COUNTER_ACC_NO ,L.TRADE_COUNTER_ACC_NAME = TEMP.TRADE_COUNTER_ACC_NAME ,L.TRADE_COUNTER_ACC_BANK_NAME = TEMP.TRADE_COUNTER_ACC_BANK_NAME ,L.TRADE_COUNTER_ACC_BANK_NO = TEMP.TRADE_COUNTER_ACC_BANK_NO ,L.TRADE_CCY = TEMP.TRADE_CCY ,L.TRADE_AMT = TEMP.TRADE_AMT ,L.TRADE_VDATE = TEMP.TRADE_VDATE ,L.TRADE_TIME = TEMP.TRADE_TIME ,L.POSTSCRIPT = TEMP.POSTSCRIPT ,L.REMARK = TEMP.REMARK ,L.RECEPT_DATE = TEMP.RECEPT_DATE ,L.CREATE_USER = TEMP.CREATE_USER ,L.ORG_CODE = TEMP.ORG_CODE ,L.CREATE_DEPT = TEMP.CREATE_DEPT ,L.CREATE_TIME = TEMP.CREATE_TIME ,L.UPDATE_USER = TEMP.UPDATE_USER ,L.UPDATE_TIME = TEMP.UPDATE_TIME WHEN NOT MATCHED THEN INSERT ( INSTITUTION_CODE, PRD_REGIST_CODE, ACCOUNT_NO, TRADE_NO, REGIST_SEQNO, DATA_STATUS, ACCOUNT_NAME, TRADE_PS, TRADE_COUNTER_ACC_NO, TRADE_COUNTER_ACC_NAME, TRADE_COUNTER_ACC_BANK_NAME, TRADE_COUNTER_ACC_BANK_NO, TRADE_CCY, TRADE_AMT, TRADE_VDATE, TRADE_TIME, POSTSCRIPT, REMARK, RECEPT_DATE, CREATE_USER, ORG_CODE, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME ) VALUES( TEMP.INSTITUTION_CODE,TEMP.PRD_REGIST_CODE,TEMP.ACCOUNT_NO,TEMP.TRADE_NO, TEMP.REGIST_SEQNO,TEMP.DATA_STATUS,TEMP.ACCOUNT_NAME,TEMP.TRADE_PS,TEMP.TRADE_COUNTER_ACC_NO, TEMP.TRADE_COUNTER_ACC_NAME,TEMP.TRADE_COUNTER_ACC_BANK_NAME,TEMP.TRADE_COUNTER_ACC_BANK_NO,TEMP.TRADE_CCY, TEMP.TRADE_AMT,TEMP.TRADE_VDATE,TEMP.TRADE_TIME,TEMP.POSTSCRIPT,TEMP.REMARK,TEMP.RECEPT_DATE,TEMP.CREATE_USER, TEMP.ORG_CODE,TEMP.CREATE_DEPT,TEMP.CREATE_TIME,TEMP.UPDATE_USER,TEMP.UPDATE_TIME )
